 const stores=Array.isArray((data.retail||{}).stores)?data.retail.stores:[];const jp=stores.find(x=>/jaipur/i.test(x.name||''));if(jp)cards.push(card('idea','RETAIL / LOCAL PROOF','Use Jaipur to make the online creative feel real.','Film a staff-led '+safe('Barrowfield / Rothwell')+' fit comparison at Jaipur. Use the content on Shopify and marketplace listings; test the same presentation at PTG instead of assuming both stores need the same display.','The supplied Jaipur bill list includes '+safe((jp.billList||[]).filter(b=>(b.items||[]).some(x=>/^(Barrowfield|Rothwell) /.test(x.sku||''))).map(b=>b.no).join(', ')||'no matching bill references in this read')+'. Myntra\'s 8 Oct 2025 BFF release names Jaipur among its high-traction non-metro markets. That is historical platform context, not Dressjet customer-location data.','Record front/side/back fit and ask one useful question: "Dinner, office or travel?" Log each store\'s answers before allocating rail space. Do not infer the third store from a feed that currently shows only two store rows.','LOW · staff video + enquiry tally',time('Retail product sales',retailAt)+' · '+checked,link(source.myntra,'Myntra BFF2025 · Jaipur context')+route('retail','Open store evidence'),'qualified enquiries and sales by store, rather than combined retail revenue.'));
