 const pending=rows.reduce((n,x)=>n+(num(x.pendingUnits)||0),0);const notes=pending?'Retail '+safe((R.pendingBills||[]).join(', ')||'pending bills')+' contains '+safe(pending)+' pending units. Revenue is unknown, not a free item. Those units are excluded from price/bundle arithmetic.':'Pending line amounts stay unknown, never zero.';
