/* Auto-update: the installed app stays alive in memory, so it never re-reads new files by itself. Compare the live files with what is running; reload when they differ. */
const UPD_FILES=['index.html','app.js','crypto.js','style.css','config.js'];let updBase=null,updBusy=false;
async function updHash(){const t=await Promise.all(UPD_FILES.map(f=>fetch(f+'?u='+Date.now(),{cache:'no-store'}).then(r=>r.ok?r.text():'')));let h=5381,x=t.join('\u0001');for(let i=0;i<x.length;i++)h=((h<<5)+h+x.charCodeAt(i))|0;return h+':'+x.length}
function updPill(m,tap){let e=document.getElementById('updp');if(!e){e=document.createElement('button');e.id='updp';e.type='button';e.style.cssText='position:fixed;left:50%;top:max(12px,env(safe-area-inset-top));transform:translateX(-50%);z-index:90;padding:8px 16px;border-radius:99px;border:1px solid var(--edge);background:var(--sf);color:var(--ink);font-size:12.5px;font-weight:700;-webkit-backdrop-filter:blur(18px);backdrop-filter:blur(18px)';document.body.appendChild(e)}e.textContent=m;e.onclick=tap||null}
